		t.Fatal(err)
	}
	if _, err := w.Apply(RequestInput{
		PolicyID: "pol1", RequestID: "r1", AccountID: "u1", SessionID: "s1",
		DeviceID: "dev1", Operation: "pay", Payee: "shop", EstimatedFee: 100,
