func TestBackupEmptyWallet(t *testing.T) {
	w := New()
	data, err := w.Export()
	if err != nil {
		t.Fatal(err)
	}
	w2, err := Restore(data)
	if err != nil {
		t.Fatal(err)
	}
	if len(w2.Ledger()) != 0 {
		t.Fatalf("empty restored wallet has ledger entries: %+v", w2.Ledger())
	}
	// 空钱包也能导出，导出不新增备份账本记录。
	data2, err := w2.Export()
	if err != nil {
		t.Fatal(err)
	}
	if data != data2 {
		t.Fatalf("empty wallet round-trip mismatch:\n%s\nvs\n%s", data, data2)
	}
}

